/* Lagos Urban Heat Island web map — observed epochs + scenario projections.
 * Every number shown is read from docs/data/*, generated by notebooks/lagos_uhi_lst.ipynb. */
(async function () {
  const DATA = "data/";
  const fmt = (v, d = 1) => (v == null || Number.isNaN(v) ? "–" : Number(v).toFixed(d));
  const sgn = (v, d = 1) => (v == null ? "–" : (v > 0 ? "+" : "") + Number(v).toFixed(d));
  const pct = (v) => (v == null ? "–" : (v * 100).toFixed(1) + "%");
  const $ = (id) => document.getElementById(id);
  const banner = $("banner");

  async function getJSON(name) {
    const r = await fetch(DATA + name, { cache: "no-cache" });
    if (!r.ok) throw new Error(`${name}: HTTP ${r.status}`);
    return r.json();
  }
  let S, LGA, PANEL, P;
  try {
    [S, LGA, PANEL, P] = await Promise.all([getJSON("summary.json"), getJSON("lga.geojson"),
      getJSON("lga_panel.json"), getJSON("projections.json")]);
  } catch (e) {
    banner.hidden = false;
    banner.textContent = "Analysis outputs not found in docs/data/. Run notebooks/lagos_uhi_lst.ipynb and unzip its output into the repo. (" + e.message + ")";
    $("kpis").innerHTML = '<p class="empty">No data loaded.</p>';
    return;
  }
  if (S.synthetic) {
    banner.hidden = false; banner.classList.add("synthetic");
    banner.textContent = "SYNTHETIC TEST DATA — layout check only. These are not Landsat results.";
  }

  const EP = Object.fromEntries(S.epochs.map((e) => [e.id, e]));
  const IDS = S.epochs.map((e) => e.id);
  const FIRST = S.first, LAST = S.last, BASE = P.base_year, PY = P.proj_years, PLAST = String(PY[PY.length - 1]);
  const panel = {}; // panel[epoch][lga]
  PANEL.forEach((r) => { (panel[r.epoch] = panel[r.epoch] || {})[r.lga] = r; });

  $("lab-change").textContent = `Change ${FIRST}→${LAST}`;
  $("lab-persist").textContent = `Hotspots ${FIRST} vs ${LAST}`;
  $("lab-built").textContent = `New built-up ${FIRST}→${LAST}`;
  $("proj-title").textContent = `${PLAST} scenarios by LGA`;
  $("built-title").textContent = `Built-up expansion, ${FIRST} → ${LAST}`;

  // ---------- colour ramp ----------
  const hex = (h) => { const n = parseInt(h, 16); return [n >> 16, (n >> 8) & 255, n & 255]; };
  function rampFn(pal, lo, hi) {
    return (v) => {
      if (v == null) return "#ccc";
      const t = Math.max(0, Math.min(1, (v - lo) / (hi - lo))) * (pal.length - 1);
      const i = Math.min(Math.floor(t), pal.length - 2), f = t - i, a = hex(pal[i]), b = hex(pal[i + 1]);
      return `rgb(${a.map((x, k) => Math.round(x + (b[k] - x) * f)).join(",")})`;
    };
  }
  const rampExcess = rampFn(S.pal_lst, S.excess_range[0], S.excess_range[1]);

  // ---------- map ----------
  const bounds = L.latLngBounds(S.bounds);
  const map = L.map("map", { zoomSnap: 0.25, minZoom: 8, maxBounds: bounds.pad(0.6) }).fitBounds(bounds);
  // Esri World Light Gray Canvas (no API key required) + reference labels on top
  L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: 16, attribution: "Basemap &copy; Esri, HERE, Garmin, &copy; OpenStreetMap contributors, and the GIS user community",
  }).addTo(map);
  const labels = L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Reference/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: 16,
  });
  map.attributionControl.addAttribution("LST: USGS Landsat C2 L2 · Built-up: Google Dynamic World");

  const state = { epoch: LAST, mode: "excess" };
  const surface = L.imageOverlay(DATA + `excess_${state.epoch}.png`, bounds, { opacity: 0.8 }).addTo(map);
  const extra = {
    change: L.imageOverlay(DATA + "change.png", bounds, { opacity: 0.85 }),
    persist: L.imageOverlay(DATA + "hotspots_change.png", bounds, { opacity: 0.9 }),
    built: L.imageOverlay(DATA + "new_built.png", bounds, { opacity: 0.9 }),
  };
  const lgaRow = (lga) => panel[state.epoch] && panel[state.epoch][lga];

  function popupHtml(lga) {
    const r = lgaRow(lga) || {}, e = EP[state.epoch], pj = P.lga[lga];
    let html = `<strong>${lga}</strong> · ${e.label}<br>
      Mean LST: ${fmt(r.lst_mean)} °C<br>
      Heat excess: <b>${sgn(r.heat_excess)} °C</b><br>
      Built-up share: ${pct(r.built_share)} · NDVI ${fmt(r.ndvi_mean, 2)}<br>
      Valid pixels: ${pct(r.coverage)}${(r.coverage || 0) < S.coverage_min_lga ? " ⚠ low" : ""}`;
    if (pj) {
      html += `<hr style="border:0;border-top:1px solid #ddd">Built-up growth ${FIRST}–${LAST}: ${sgn(pj.growth_pp_per_yr, 2)} pp/yr`;
      PY.forEach((y) => { const p = pj[String(y)];
        html += `<br>${y}: S1 <b>${sgn(p.S1)}</b> [${fmt(p.S1_ci[0])}, ${fmt(p.S1_ci[1])}] · S2 <b>${sgn(p.S2)}</b> [${fmt(p.S2_ci[0])}, ${fmt(p.S2_ci[1])}] °C`; });
    }
    return html;
  }

  const lgaLayer = L.geoJSON(LGA, {
    style: () => ({ color: "#222", weight: 1, fillOpacity: 0, dashArray: "3 3" }),
    onEachFeature: (f, layer) => {
      const name = f.properties.lga;
      layer.bindPopup(() => popupHtml(name), { maxWidth: 320 });
      layer.bindTooltip(name, { sticky: true, direction: "top", opacity: 0.9 });
      layer.on({
        mouseover: (e) => { const r = lgaRow(name); e.target.setStyle({ weight: 2.5, dashArray: null, fillColor: rampExcess(r && r.heat_excess), fillOpacity: 0.15 }); },
        mouseout: (e) => lgaLayer.resetStyle(e.target),
      });
    },
  }).addTo(map);

  map.createPane("labels"); map.getPane("labels").style.zIndex = 650; map.getPane("labels").style.pointerEvents = "none";
  labels.options.pane = "labels"; labels.addTo(map);

  const legend = L.control({ position: "bottomleft" });
  legend.onAdd = () => L.DomUtil.create("div", "legend");
  legend.addTo(map);
  function drawLegend() {
    const [lo, hi] = state.mode === "lst" ? S.lst_range : S.excess_range;
    const title = state.mode === "lst" ? "Land surface temperature (°C)" : "Heat excess vs. vegetated land (°C)";
    let h = `<strong>${title}</strong>
      <div class="bar" style="background:linear-gradient(90deg,${S.pal_lst.map((c) => "#" + c).join(",")})"></div>
      <div class="ticks"><span>≤${lo}</span><span>${Math.round((lo + hi) / 2)}</span><span>≥${hi}</span></div>`;
    if (map.hasLayer(extra.change)) h += `<div style="margin-top:6px"><strong>Change in heat excess ${FIRST}→${LAST}</strong>
      <div class="bar" style="background:linear-gradient(90deg,${S.pal_div.map((c) => "#" + c).join(",")})"></div>
      <div class="ticks"><span>${S.change_range[0]}</span><span>0</span><span>+${S.change_range[1]}</span></div></div>`;
    if (map.hasLayer(extra.persist)) h += `<div style="margin-top:6px"><strong>Hotspots (excess ≥ ${fmt(S.hotspot.threshold_c)} °C)</strong>
      <div class="row"><i style="background:#a50026"></i>Hot in ${FIRST} and ${LAST}</div>
      <div class="row"><i style="background:#fdae61"></i>New by ${LAST}</div>
      <div class="row"><i style="background:#4575b4"></i>Hot in ${FIRST} only</div></div>`;
    if (map.hasLayer(extra.built)) h += `<div class="row" style="margin-top:6px"><i style="background:#6a3d9a"></i>New built-up ${FIRST}→${LAST}</div>`;
    legend.getContainer().innerHTML = h;
  }

  // ---------- controls ----------
  IDS.forEach((id) => {
    const b = document.createElement("button");
    b.textContent = id; b.dataset.id = id; b.title = EP[id].label;
    b.onclick = () => { state.epoch = id; update(); };
    $("epochs").appendChild(b);
  });
  document.querySelectorAll("#modes button").forEach((b) => (b.onclick = () => { state.mode = b.dataset.mode; update(); }));
  const toggle = (id, layer) => $(id).addEventListener("change", (e) => {
    e.target.checked ? layer.addTo(map) : map.removeLayer(layer); drawLegend(); });
  toggle("t-surface", surface); toggle("t-change", extra.change); toggle("t-persist", extra.persist);
  toggle("t-built", extra.built); toggle("t-lga", lgaLayer);
  $("op").addEventListener("input", (e) => surface.setOpacity(+e.target.value));

  // ---------- epoch table ----------
  $("epoch-table").innerHTML = `<tr><th>Dec</th><th>L8+L9</th><th>Valid</th><th>SUHI °C</th><th>Hot km²</th></tr>` +
    IDS.map((id) => { const e = EP[id];
      return `<tr><td>${e.id}</td><td>${e.landsat8}+${e.landsat9}</td><td>${pct(e.coverage)}</td><td>${sgn(e.suhi)}</td><td>${fmt(e.hot_km2, 0)}</td></tr>`; }).join("");
  $("epoch-table").insertAdjacentHTML("afterend", `<p class="note">SUHI = built-up − vegetated mean LST.
    Hotspot = heat excess ≥ ${fmt(S.hotspot.threshold_c)} °C (fixed ${FIRST} threshold, so km² is comparable across epochs).</p>`);

  // ---------- charts ----------
  Chart.defaults.font.size = 11; Chart.defaults.color = "#5f6368";
  const grid = { color: "#eceae5" };

  const obs = P.aggregate.observed, last = obs[obs.length - 1];
  const line = (s) => [{ x: last.year, y: last.he }, ...P.aggregate[s].map((p) => ({ x: p.year, y: p.he }))];
  const band = (s, k) => [{ x: last.year, y: last.he }, ...P.aggregate[s].map((p) => ({ x: p.year, y: p.ci[k] }))];
  new Chart($("c-trend"), {
    type: "line",
    data: { datasets: [
      { label: "Observed", data: obs.map((o) => ({ x: o.year, y: o.he })), borderColor: "#1d1d1f", backgroundColor: "#1d1d1f", pointRadius: 3 },
      { label: "S1 growth continues", data: line("S1"), borderColor: "#d73027", backgroundColor: "#d73027", borderDash: [5, 4], pointRadius: 3 },
      { label: "S1 lo", data: band("S1", 0), borderWidth: 0, pointRadius: 0, fill: false },
      { label: "S1 hi", data: band("S1", 1), borderWidth: 0, pointRadius: 0, fill: "-1", backgroundColor: "rgba(215,48,39,.15)" },
      { label: "S2 no further growth", data: line("S2"), borderColor: "#4575b4", backgroundColor: "#4575b4", borderDash: [5, 4], pointRadius: 3 },
      { label: "S2 lo", data: band("S2", 0), borderWidth: 0, pointRadius: 0, fill: false },
      { label: "S2 hi", data: band("S2", 1), borderWidth: 0, pointRadius: 0, fill: "-1", backgroundColor: "rgba(69,117,180,.15)" },
    ] },
    options: { maintainAspectRatio: false, parsing: false,
      plugins: { legend: { position: "bottom", labels: { boxWidth: 12, filter: (i) => !/ (lo|hi)$/.test(i.text) } },
        tooltip: { filter: (i) => !/ (lo|hi)$/.test(i.dataset.label) } },
      scales: { x: { type: "linear", min: obs[0].year, max: +PLAST, ticks: { stepSize: 2, callback: (v) => (v > BASE ? v + "ᵖ" : v) }, grid },
        y: { title: { display: true, text: "Mean heat excess (°C)" }, grid } } },
  });

  const H = P.hindcast;
  const beats = H.model.mae < H.no_change_baseline.mae;
  $("model").innerHTML = `
    <div>β (expansion): <b>${sgn(P.beta_per_10pp, 2)} °C</b> per +10 pp built-up [${fmt(P.beta_per_10pp_ci[0], 2)}, ${fmt(P.beta_per_10pp_ci[1], 2)}]</div>
    <div>γ (background drift): <b>${sgn(P.gamma_per_yr, 3)} °C/yr</b> [${fmt(P.gamma_per_yr_ci[0], 3)}, ${fmt(P.gamma_per_yr_ci[1], 3)}]</div>
    <div style="margin-top:4px">Hindcast (fit ${H.trained_on.join(", ")} → predict ${H.predicted}, ${H.n_lgas} LGAs): model MAE <b>${fmt(H.model.mae, 2)} °C</b>
      vs. no-change baseline ${fmt(H.no_change_baseline.mae, 2)} °C — ${beats ? "model beats the baseline" : "model does <b>not</b> beat the baseline; treat projections as indicative"}.</div>
    <div class="note">ᵖ projected. ${P.n_lgas} LGAs with valid data in all ${P.obs_years.length} epochs; ${P.bootstrap_draws} bootstrap draws.</div>`;

  const lgaChart = new Chart($("c-lga"), {
    type: "bar", data: { labels: [], datasets: [{ data: [], backgroundColor: [] }] },
    options: { indexAxis: "y", maintainAspectRatio: false, plugins: { legend: { display: false } },
      scales: { x: { grid, title: { display: true, text: "Heat excess (°C)" } }, y: { grid: { display: false } } },
      onClick: (_, els) => { if (!els.length) return; const name = lgaChart.data.labels[els[0].index];
        lgaLayer.eachLayer((l) => { if (l.feature.properties.lga === name) { map.fitBounds(l.getBounds()); l.openPopup(); } }); } },
  });

  const pr = Object.entries(P.lga).sort((a, b) => b[1][PLAST].S1 - a[1][PLAST].S1);
  new Chart($("c-proj"), {
    type: "bar",
    data: { labels: pr.map(([l]) => l), datasets: [
      { label: `${BASE} observed`, data: pr.map(([, v]) => v.he_base), backgroundColor: "#9e9e9e" },
      { label: `${PLAST} S2 no growth`, data: pr.map(([, v]) => v[PLAST].S2), backgroundColor: "#4575b4" },
      { label: `${PLAST} S1 growth continues`, data: pr.map(([, v]) => v[PLAST].S1), backgroundColor: "#d73027" },
    ] },
    options: { indexAxis: "y", maintainAspectRatio: false, plugins: { legend: { position: "bottom", labels: { boxWidth: 12 } } },
      scales: { x: { grid, title: { display: true, text: "Heat excess (°C)" } }, y: { grid: { display: false } } } },
  });

  const bl = Object.keys(panel[FIRST]).sort((a, b) => ((panel[LAST][b] || {}).built_share || 0) - ((panel[LAST][a] || {}).built_share || 0));
  new Chart($("c-built"), {
    type: "bar",
    data: { labels: bl, datasets: [
      { label: FIRST, data: bl.map((l) => +(((panel[FIRST][l] || {}).built_share || 0) * 100).toFixed(1)), backgroundColor: "#bdbdbd" },
      { label: LAST, data: bl.map((l) => +(((panel[LAST][l] || {}).built_share || 0) * 100).toFixed(1)), backgroundColor: "#6a3d9a" },
    ] },
    options: { indexAxis: "y", maintainAspectRatio: false, plugins: { legend: { position: "bottom", labels: { boxWidth: 12 } } },
      scales: { x: { grid, max: 100, title: { display: true, text: "Built-up share of land (%)" } }, y: { grid: { display: false } } } },
  });

  // ---------- update on epoch / mode change ----------
  function update() {
    const e = EP[state.epoch];
    surface.setUrl(DATA + `${state.mode === "lst" ? "lst" : "excess"}_${state.epoch}.png`);
    document.querySelectorAll("#epochs button").forEach((b) => b.classList.toggle("on", b.dataset.id === state.epoch));
    document.querySelectorAll("#modes button").forEach((b) => b.classList.toggle("on", b.dataset.mode === state.mode));
    $("epoch-title").textContent = `${e.label} · dry season`;
    $("kpis").innerHTML = `
      <div class="kpi main"><div class="v">${sgn(e.suhi)} °C</div><div class="l">Surface UHI intensity, built-up − vegetated</div></div>
      <div class="kpi"><div class="v">${fmt(e.urban_mean)} °C</div><div class="l">Built-up mean LST (± ${fmt(e.urban_std)})</div></div>
      <div class="kpi"><div class="v">${fmt(e.rural_mean)} °C</div><div class="l">Vegetated mean LST (± ${fmt(e.rural_std)})</div></div>
      <div class="kpi"><div class="v">${e.landsat8 + e.landsat9}</div><div class="l">Landsat scenes (L8 ${e.landsat8} · L9 ${e.landsat9})</div></div>
      <div class="kpi"><div class="v">${fmt(e.hot_km2, 0)} km²</div><div class="l">Hotspot area</div></div>`;
    $("epoch-note").textContent = `Imagery ${e.start} to ${e.end} (end exclusive); ${pct(e.coverage)} of land with valid LST.`;

    const rows = Object.entries(panel[state.epoch] || {})
      .filter(([, r]) => r.heat_excess != null && (r.coverage || 0) >= S.coverage_min_lga)
      .map(([l, r]) => ({ l, v: r.heat_excess })).sort((a, b) => b.v - a.v);
    $("lga-title").textContent = `Heat excess by LGA — ${e.label}`;
    lgaChart.data.labels = rows.map((d) => d.l);
    lgaChart.data.datasets[0].data = rows.map((d) => d.v);
    lgaChart.data.datasets[0].backgroundColor = rows.map((d) => rampExcess(d.v));
    lgaChart.update();
    drawLegend();
  }
  update();
})();
